import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Transistor e chip di silicio","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/p_matematica-per-informatica/pd/pdad.md","filePath":"lezioni/p_matematica-per-informatica/pd/pdad.md"}`),a={name:`lezioni/p_matematica-per-informatica/pd/pdad.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="transistor-e-chip-di-silicio" tabindex="-1">Transistor e chip di silicio <a class="header-anchor" href="#transistor-e-chip-di-silicio" aria-label="Permalink to “Transistor e chip di silicio”">​</a></h1><h3 id="brevi-cenni-di-storia" tabindex="-1">brevi cenni di storia <a class="header-anchor" href="#brevi-cenni-di-storia" aria-label="Permalink to “brevi cenni di storia”">​</a></h3><p>Attorno agli anni <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>50</mn></mrow><annotation encoding="application/x-tex">50</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">50</span></span></span></span> fu inventato il transistor, che si può comportare come un diodo, e quindi come un interruttore, le cui dimensioni, però, rispetto alle valvole sono notevolmente ridotte: questo ha permesso di passare da computer delle dimensioni di un appartamento a computer delle dimensioni di una stanza.</p><blockquote><p>Ricordo che nel <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1959</mn></mrow><annotation encoding="application/x-tex">1959</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1959</span></span></span></span> comperai la mia prima radiolina a transistor (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>7</mn></mrow><annotation encoding="application/x-tex">7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">7</span></span></span></span> transistor!): il transistor aveva permesso la costruzione di una radiolina portatile al posto delle radio a valvole che erano parecchio ingombranti e questo permetteva di portarsi dietro ovunque la radiolina un po&#39; come fate voi oggi con i telefonini.</p></blockquote><p>Attorno agli anni <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>60</mn></mrow><annotation encoding="application/x-tex">60</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">60</span></span></span></span> poi, si è passati ai chip di silicio: lenti di silicio purissimo venivano trattate con strati di sostanze speciali e poi tali strati venivano asportati su linee a varie profondità costituendo circuiti, diodi, ed altri apparati elettrici in miniatura: i computer divennero delle dimensioni di un tavolo.</p><p>Infine negli anni <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>70</mn></mrow><annotation encoding="application/x-tex">70</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">70</span></span></span></span>, con i microchip, chip di silicio ove i componenti venivano lavorati a scale microscopiche, il computer arrivò alle dimensioni attuali e nei primi anni <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>80</mn></mrow><annotation encoding="application/x-tex">80</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">80</span></span></span></span> nasceva il primo personal computer e nel <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1984</mn></mrow><annotation encoding="application/x-tex">1984</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1984</span></span></span></span> anche un computer dotato di interfaccia grafica e mouse.</p><p>Comunque, chiudendo l&#39;argomento, abbiamo un interruttore che possiamo far aprire o chiudere da una corrente elettrica e questo, per i nostri circuiti, ci è sufficiente.</p>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};